"""Temporary differential check: new pricing vs the original implementation."""
import itertools
import random
from decimal import Decimal, ROUND_HALF_UP

import pricing


def legacy_checkout(cart, customer, coupon=None):
    total = Decimal("0")
    lines = []
    for item in cart:
        p = Decimal(str(item["price"]))
        q = item["qty"]
        if q <= 0:
            continue
        if customer.get("tier") == "silver":
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.95")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.95")
        elif customer.get("tier") == "platinum":
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.80")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
                line = line * Decimal("0.80")
        else:
            if item.get("category") == "books":
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
            else:
                line = p * q
                if q >= 10:
                    line = line * Decimal("0.9")
        if item.get("category") == "books":
            tax = Decimal("0.07")
        elif item.get("category") == "food":
            tax = Decimal("0.07")
        else:
            tax = Decimal("0.19")
        line = line.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        t = (line * tax).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        lines.append({"sku": item["sku"], "net": line, "tax": t})
        total = total + line + t
    if coupon is not None:
        if coupon == "WELCOME5":
            if total >= Decimal("20"):
                total = total - Decimal("5")
        elif coupon == "HALFSHIP":
            pass
        elif coupon.startswith("PCT"):
            pct = int(coupon[3:])
            if pct > 30:
                pct = 30
            total = total - (total * pct / 100).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        else:
            raise ValueError("unknown coupon")
    if total < 0:
        total = Decimal("0")
    return {"lines": lines, "total": total.quantize(Decimal("0.01"))}


def outcome(fn, *args):
    try:
        return ("ok", fn(*args))
    except Exception as exc:  # noqa: BLE001 - differential harness
        return ("err", type(exc).__name__, str(exc))


prices = [0, 1, 10, "12.99", "3.33", "0.005", "1.005", "19.995", "0.01", "123.456"]
qtys = [-1, 0, 1, 2, 9, 10, 11, 25]
categories = [None, "books", "food", "other", "electronics", "BOOKS", ""]
tiers = [None, "", "silver", "platinum", "bronze", "gold"]
coupons = [None, "WELCOME5", "HALFSHIP", "PCT0", "PCT5", "PCT30", "PCT50", "BAD"]

rng = random.Random(1234)
checked = 0

# Systematic single-item cases across every dimension (gold handled after).
for price, qty, category, tier, coupon in itertools.product(
    prices, qtys, categories, tiers, coupons
):
    if tier == "gold":
        continue
    item = {"sku": "X", "price": price, "qty": qty}
    if category is not None:
        item["category"] = category
    customer = {} if tier is None else {"tier": tier}
    old = outcome(legacy_checkout, [item], customer, coupon)
    new = outcome(pricing.checkout, [item], customer, coupon)
    assert old == new, (item, customer, coupon, old, new)
    checked += 1

# Random multi-item carts, including duplicate SKUs and qty<=0 lines.
for _ in range(5000):
    cart = []
    for i in range(rng.randint(0, 6)):
        item = {
            "sku": "S%d" % i,
            "price": rng.choice(prices),
            "qty": rng.choice(qtys),
        }
        category = rng.choice(categories)
        if category is not None:
            item["category"] = category
        cart.append(item)
    tier = rng.choice([t for t in tiers if t != "gold"])
    customer = {} if tier is None else {"tier": tier}
    coupon = rng.choice(coupons)
    old = outcome(legacy_checkout, cart, customer, coupon)
    new = outcome(pricing.checkout, cart, customer, coupon)
    assert old == new, (cart, customer, coupon, old, new)
    checked += 1

# Gold must match the silver/platinum code path shape with a 12% discount.
def expected_gold(item):
    line = Decimal(str(item["price"])) * item["qty"]
    if item["qty"] >= 10:
        line = line * Decimal("0.9")
    line = line * Decimal("0.88")
    tax = Decimal("0.07") if item.get("category") in ("books", "food") else Decimal("0.19")
    net = line.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    return {"sku": item["sku"], "net": net,
            "tax": (net * tax).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)}


for price, qty, category in itertools.product(prices, [1, 9, 10, 15], categories):
    item = {"sku": "G", "price": price, "qty": qty}
    if category is not None:
        item["category"] = category
    assert pricing.price_line(item, {"tier": "gold"}) == expected_gold(item)
    checked += 1

assert pricing.checkout([{"sku": "A", "price": 100, "qty": 1}], {"tier": "gold"})["total"] == Decimal("104.72")
assert "gold" in pricing.TIER_DISCOUNTS
assert pricing.TIER_DISCOUNTS["gold"] == Decimal("0.12")
print("differential cases checked:", checked)
print("all equivalent (gold intentionally differs; verified separately)")

